<script lang="ts">import type {PageData} from './$types';export let data:PageData;let tasks=data.tasks;const lanes=['backlog','next','doing','blocked','done'];let title='';async function refresh(){tasks=(await (await fetch('/api/board/tasks?includeDone=1')).json()).tasks||[]}async function add(){if(!title.trim())return;await fetch('/api/board/tasks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title})});title='';await refresh()}async function move(id:string,lane:string){await fetch('/api/board/tasks',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id,lane})});await refresh()}</script>
<div class="hii-page grid gap-6 lg:grid-cols-[210px_minmax(0,1fr)]"><aside class="hii-side-nav"><a href="/feed" class="hii-side-link">Feed</a><a href="/boards" class="hii-side-link" data-active="true">Boards</a><a href="/console" class="hii-side-link">Console</a><a href="/credits" class="hii-side-link">Credits</a></aside><div class="space-y-5"><header class="hii-page-header"><p class="hii-kicker">hii board</p><h1 class="hii-page-title">Tasks as a command surface.</h1><p class="hii-page-copy text-sm">Local kanban for agent work, project tracks, and next actions.</p></header><div class="hii-terminal-frame p-3 font-mono text-xs">hii board · store {data.store}</div><div class="hii-card flex gap-2"><input class="hii-field flex-1 px-3 py-2" bind:value={title} placeholder="Add bounded task"/><button class="hii-command-button" on:click={add}>Add</button></div><div class="grid gap-3 xl:grid-cols-5">{#each lanes as lane}<section class="hii-card min-h-48"><h2 class="font-mono text-xs uppercase">{lane} · {tasks.filter(t=>t.lane===lane).length}</h2>{#each tasks.filter(t=>t.lane===lane) as task}<article class="mt-3 border-t pt-3"><strong class="text-sm">{task.title}</strong><p class="mt-1 font-mono text-[10px] text-neutral-500">{task.owner} · {task.priority}</p><select class="hii-select mt-2 w-full text-xs" value={task.lane} on:change={(e)=>move(task.id,e.currentTarget.value)}>{#each lanes as target}<option value={target}>{target}</option>{/each}</select></article>{/each}</section>{/each}</div></div></div>
